Check("ToLower", "ABC".ToLower(), "abc")
Check("Trim", "  x  ".Trim(), "x")
Check("TrimStart", "  x  ".TrimStart(), "x  ")
Check("TrimEnd", "  x  ".TrimEnd(), "  x")
