        b.Pressed = true
        ui.Draw()
        print("gedrueckt " + (part.Background == red))
        b.Pressed = false
        ui.Draw()
        print("losgelassen " + (part.Background == green))
        b.Text = "hi"
        ui.Draw()
        print("text " + b.FindPart("txt").Text + " " + b.actualWidth)
        var tb = new UI.TextBox("abc")
