        tb.Text = "xyz"
        ui.Draw()
        print("quelle " + l2.Text + " " + l3.Text)
        l3.Text = "zurueck"
        ui.Draw()
        ui.Draw()
        print("ziel " + tb.Text + " " + l2.Text)
        var tplStyle = new UI.Style("CheckBox")
