                        inline c Key(int vk, int scan) { HWND h = FindWindow((LPCSTR)"FireWindow16", (LPCSTR)"Win16"); if (h != 0) { PostMessage(h, WM_KEYDOWN, (WPARAM)vk, ((LPARAM)scan << 16) | 1); PostMessage(h, WM_KEYUP, (WPARAM)vk, ((LPARAM)scan << 16) | 0xC0000001L); } }
